file.content:
  // controls (which have no onClose of their own) can trigger the actual Drawer close.
  useEffect(() => {
    registerCloseHandler(onClose);
    return () => registerCloseHandler(null);
  }, [onClose, registerCloseHandler]);

  // Keeps the header shell's chrome state in sync however the drawer actually closes.
  useEffect(() => {
    if (!isOpen) notifyClosed();
  }, [isOpen, notifyClosed]);

  return (
    <DrawerMenuView
      isOpen={isOpen}
      onClose={onClose}
      onLogoClick={onLogoClick}
      items={items}
      isLoading={isLoading}
      activeItem={activeItem}
      isDrilledIn={isDrilledIn}
      onDrillInto={drillInto}
    />
  );
};

DrawerMenu.displayName = 'DrawerMenu';

export { DrawerMenu };
export default DrawerMenu;

